85	// Wrap a state change in a view transition when the platform offers one and
86	// the user has not asked for reduced motion; otherwise apply it directly.
87	export function withScreenTransition(update: () => void, done?: () => void) {
88	  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
89	  if (
90	    typeof document.startViewTransition !== "function" ||
91	    reduceMotion ||
92	    document.visibilityState === "hidden" // nothing to animate off-screen
93	  ) {
94	    update();
95	    done?.();
96	    return;
97	  }
98	  const transition = document.startViewTransition(() => {
99	    flushSync(update);
100	  });
101	  // A skipped or aborted transition (hidden tab, rapid re-entry) rejects
102	  // `finished`; that is normal, so swallow it and always run the cleanup.
103	  void transition.finished
104	    .catch(() => {})
105	    .then(() => done?.());
106	}
