215	// A durable breadcrumb that this browser has signed in before. It lets a
216	// returning visitor splash straight toward the app instead of flashing the
217	// landing while Clerk wakes. Reads can fail (private mode); we degrade to "no
218	// hint" rather than throw, so those visitors just meet the landing first.
219	const SESSION_HINT_KEY = "haven:hasSession";
220	
221	function readSessionHint(): boolean {
222	  try {
223	    return window.localStorage.getItem(SESSION_HINT_KEY) !== null;
224	  } catch {
225	    return false;
226	  }
227	}
228	
229	function writeSessionHint(present: boolean): void {
230	  try {
231	    if (present) window.localStorage.setItem(SESSION_HINT_KEY, "1");
232	    else window.localStorage.removeItem(SESSION_HINT_KEY);
233	  } catch {
234	    // Storage blocked -- the returning-visitor fast path simply won't apply.
235	  }
236	}
