238	export default function App() {
239	  const { isLoading, isAuthenticated } = useConvexAuth();
240	
241	  // The hash is tracked live so a "Sign in" tap on the waitlist (or the back
242	  // button) re-routes in place, without a reload.
243	  const [hash, setHash] = useState(() => window.location.hash);
244	  useEffect(() => {
245	    const onHashChange = () => setHash(window.location.hash);
246	    window.addEventListener("hashchange", onHashChange);
247	    return () => window.removeEventListener("hashchange", onHashChange);
248	  }, []);
249	
250	  // Read once at first paint -- it only steers the frame before Clerk resolves;
251	  // after that, isAuthenticated drives the choice.
252	  const [hasSessionHint] = useState(readSessionHint);
253	
254	  // Keep the hint honest against the resolved auth state: set it when signed in,
255	  // clear it the moment we resolve signed out -- covering both a sign-out and a
256	  // stale hint whose session no longer holds. Left untouched while auth loads.
257	  useEffect(() => {
258	    if (isLoading) return;
259	    writeSessionHint(isAuthenticated);
260	  }, [isLoading, isAuthenticated]);
261	
262	  const view = resolveView({ isAuthenticated, isLoading, hash, hasSessionHint });
263	  if (view === "home") return <Home />;
264	  if (view === "signin") return <SignIn />;
265	  if (view === "splash") return <Splash />;
266	  return <Waitlist />;
267	}
